import React, { useMemo, useRef, useState } from 'react';
import { Box, Button, Chip, Collapse, IconButton, Paper, Typography } from '@mui/material';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import ModelCanvas from './ModelCanvas';
import { InventoryBagPanel } from './InventoryBag';
import { sampleNavitars } from './NavitarShowcase';
import {
  PRIME_DESIGNS,
  PRIME_ZERO_DESIGN,
  REALM_CANDIDATE_DESIGNS,
} from '../utils/collectionDesigns';
import { useOwnerMode } from '../utils/ownerMode';
import { elementColor, elementEmoji } from '../utils/navitarArt';
import {
  FEED_BOND,
  TRAIN_BOND,
  TRAINING_XP,
  TWICE_DAILY_LEVEL,
  getCare,
  recordTraining,
  trainingsLeftToday,
  updateCare,
  type StageCare,
} from '../utils/training';

// The Navidex STAGE (Modern View integration, Eddie 2026-11-16):
// in 3D mode the collection stops being a grid and becomes a stage —
// one navitar standing on a lit platform, its REAL GLB model (the
// same files the battle stage and Stroll use), swipe or arrow to the
// next, and four companion actions while it stands there:
//   Modify — crystal tint + gear for the stage look
//   Feed   — a treat: bond up, happy bounce
//   Bag    — give it items from the player's bag (InventoryBag)
//   Train  — a quick elemental combo animation, XP + bond, on a
//            per-navitar daily cooldown (utils/training.ts)
// Care state (bond/XP/look) persists per navitar in localStorage —
// the companion remembers how it has been treated (the AI-companion
// principle: realness lives in the relationship, not the polygons).

interface StageFighter {
  name: string;
  element: string;
  level: number;
  modelUrl: string;
  modelZoom?: number;
  tag?: string;
}

const M = (file: string) => `${process.env.PUBLIC_URL}/models/${file}`;

const BASE_STAGE: StageFighter[] = [
  ...sampleNavitars.map(n => ({
    name: n.name,
    element: n.type,
    level: n.level ?? 10,
    modelUrl: '',
  })),
  { name: 'Ashwing', element: 'fire', level: 2, modelUrl: M('fire-phoenix.glb'), modelZoom: 1.5 },
  { name: 'Griffin', element: 'ice', level: 2, modelUrl: M('ice-griffin.glb') },
];

const BASE_MODELS: Record<string, { modelUrl: string; modelZoom?: number }> = {
  Frostbite: { modelUrl: M('frostbite-dragon.glb') },
  Emberwing: { modelUrl: M('emberwing-dragon.glb'), modelZoom: 1.45 },
  Leafblade: { modelUrl: M('leafblade.glb') },
  Shadowmaw: { modelUrl: M('shadowmaw.glb') },
  Luminara: { modelUrl: M('gold-dragon.glb') },
  Quantix: { modelUrl: M('quantix.glb') },
  Voltwing: { modelUrl: M('voltwing.glb'), modelZoom: 1.3 },
  Spiritmaw: { modelUrl: M('spiritmaw.glb') },
  Tidefang: { modelUrl: M('tidefang.glb') },
  Ashwing: { modelUrl: M('fire-phoenix.glb'), modelZoom: 1.5 },
  Griffin: { modelUrl: M('ice-griffin.glb') },
  Sundermaw: { modelUrl: M('sundermaw.glb') },
  Cindermother: { modelUrl: M('cindermother.glb') },
  Heartroot: { modelUrl: M('heartroot.glb') },
  Erebane: { modelUrl: M('erebane.glb') },
  Solara: { modelUrl: M('solara.glb') },
};

const OWNER_MODELS: Record<string, { modelUrl: string; modelZoom?: number }> = {
  'Prime Zero': { modelUrl: M('navitar-zero.glb') },
  Paradoxa: { modelUrl: M('paradoxa.glb') },
  Fulgar: { modelUrl: M('fulgar.glb') },
  Memoria: { modelUrl: M('memoria.glb') },
  Pelagia: { modelUrl: M('pelagia.glb') },
  'Ignivar the Gateforge': { modelUrl: M('ignivar.glb') },
  Hiveheart: { modelUrl: M('hiveheart.glb') },
  Aleator: { modelUrl: M('aleator.glb') },
  Ketzalli: { modelUrl: M('ketzalli.glb') },
  Sagivane: { modelUrl: M('sagivane.glb') },
  Zamurai: { modelUrl: M('zamurai.glb') },
  Umbraback: { modelUrl: M('umbraback.glb') },
  Voltstreak: { modelUrl: M('voltstreak.glb') },
};

const TINTS: { label: string; filter: string }[] = [
  { label: 'True colours', filter: 'none' },
  { label: 'Frost crystal', filter: 'hue-rotate(150deg) saturate(1.3)' },
  { label: 'Ember crystal', filter: 'hue-rotate(-35deg) saturate(1.5)' },
  { label: 'Void crystal', filter: 'hue-rotate(240deg) saturate(1.2) brightness(0.9)' },
  { label: 'Gilded', filter: 'sepia(0.7) saturate(2) hue-rotate(5deg)' },
];

const GEAR = ['Crystal Collar', 'Frost Saddle', 'Ember Harness', 'Star Charm', 'Tide Ribbon'];

const NavidexStage: React.FC = () => {
  const ownerMode = useOwnerMode();
  const roster = useMemo<StageFighter[]>(() => {
    const base = BASE_STAGE.map(f => ({ ...f, ...(BASE_MODELS[f.name] ?? {}) })).filter(
      f => f.modelUrl
    );
    if (!ownerMode) return base;
    const ownerExtras: StageFighter[] = [
      {
        name: PRIME_ZERO_DESIGN.name,
        element: PRIME_ZERO_DESIGN.element,
        level: 30,
        modelUrl: OWNER_MODELS['Prime Zero'].modelUrl,
        tag: 'PRIME ZERO — YOURS ALONE',
      },
      ...PRIME_DESIGNS.filter(d => OWNER_MODELS[d.name]).map(d => ({
        name: d.name,
        element: d.element,
        level: 25,
        modelUrl: OWNER_MODELS[d.name].modelUrl,
        modelZoom: OWNER_MODELS[d.name].modelZoom,
        tag: 'PRIME',
      })),
      ...REALM_CANDIDATE_DESIGNS.filter(d => OWNER_MODELS[d.name]).map(d => ({
        name: d.name,
        element: d.element,
        level: 20,
        modelUrl: OWNER_MODELS[d.name].modelUrl,
        modelZoom: OWNER_MODELS[d.name].modelZoom,
        tag: 'REALM BATCH CANDIDATE',
      })),
    ];
    const seen = new Set(base.map(f => f.name));
    return [...ownerExtras.filter(f => !seen.has(f.name)), ...base];
  }, [ownerMode]);

  const [index, setIndex] = useState(0);
  const fighter = roster[Math.min(index, roster.length - 1)];
  const [care, setCare] = useState<StageCare>(() => getCare(fighter.name));
  const [panel, setPanel] = useState<'none' | 'modify' | 'bag'>('none');
  const [anim, setAnim] = useState<'training' | 'feeding' | null>(null);
  const [burst, setBurst] = useState(false);
  const [note, setNote] = useState<string | null>(null);
  const touchX = useRef<number | null>(null);

  const goTo = (next: number) => {
    const wrapped = (next + roster.length) % roster.length;
    setIndex(wrapped);
    setCare(getCare(roster[wrapped].name));
    setPanel('none');
    setNote(null);
  };

  const left = trainingsLeftToday(fighter.name, fighter.level);

  const flash = (kind: 'training' | 'feeding', withBurst: boolean, message: string) => {
    setAnim(kind);
    if (withBurst) setBurst(true);
    setNote(message);
    window.setTimeout(() => {
      setAnim(null);
      setBurst(false);
    }, 950);
  };

  const onTrain = () => {
    if (left <= 0) {
      setNote(
        `${fighter.name} has trained enough today — the cooldown resets tomorrow. Rest is part of training.`
      );
      return;
    }
    recordTraining(fighter.name);
    const next = updateCare(fighter.name, {
      xp: care.xp + TRAINING_XP,
      bond: care.bond + TRAIN_BOND,
    });
    setCare(next);
    flash(
      'training',
      true,
      `${fighter.name} trained! +${TRAINING_XP} XP · +${TRAIN_BOND} bond · ${
        left - 1 > 0 ? `${left - 1} session left today` : 'daily training complete'
      }`
    );
  };

  const onFeed = () => {
    const next = updateCare(fighter.name, { bond: care.bond + FEED_BOND });
    setCare(next);
    flash('feeding', false, `${fighter.name} loved that. +${FEED_BOND} bond.`);
  };

  const toggleGear = (item: string) => {
    const gear = care.gear.includes(item)
      ? care.gear.filter(g => g !== item)
      : [...care.gear, item];
    const next = updateCare(fighter.name, { gear });
    setCare(next);
  };

  return (
    <Box sx={{ mb: 5 }}>
      <Box
        className="glacer-stage"
        onTouchStart={e => {
          touchX.current = e.touches[0].clientX;
        }}
        onTouchEnd={e => {
          if (touchX.current === null) return;
          const dx = e.changedTouches[0].clientX - touchX.current;
          touchX.current = null;
          if (Math.abs(dx) > 48) goTo(index + (dx < 0 ? 1 : -1));
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', p: 2 }}>
          <IconButton
            aria-label="Previous navitar"
            onClick={() => goTo(index - 1)}
            sx={{ color: '#eaf6fa' }}
          >
            <ChevronLeftIcon fontSize="large" />
          </IconButton>
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" sx={{ color: '#eaf6fa', fontWeight: 700 }}>
              {elementEmoji(fighter.element)} {fighter.name}
            </Typography>
            <Typography variant="body2" sx={{ color: '#9dbec9' }}>
              {fighter.element} · Lv. {fighter.level} · Bond {care.bond} · XP {care.xp}
            </Typography>
            {fighter.tag && (
              <Chip
                label={fighter.tag}
                size="small"
                sx={{ mt: 0.75, bgcolor: '#ffd54f', color: '#4a3500', fontWeight: 'bold' }}
              />
            )}
          </Box>
          <IconButton
            aria-label="Next navitar"
            onClick={() => goTo(index + 1)}
            sx={{ color: '#eaf6fa' }}
          >
            <ChevronRightIcon fontSize="large" />
          </IconButton>
        </Box>

        <div className="glacer-stage-floor" />
        <div
          className={`glacer-stage-model${anim ? ` ${anim}` : ''}`}
          style={{ filter: care.tint }}
        >
          <ModelCanvas
            key={fighter.name}
            modelUrl={fighter.modelUrl}
            zoom={fighter.modelZoom}
            grounded
            onLoaded={() => undefined}
            onError={() => undefined}
          />
          {burst && (
            <div className="glacer-burst" style={{ color: elementColor(fighter.element) }}>
              {elementEmoji(fighter.element)}
            </div>
          )}
        </div>

        <Box
          sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap', px: 2, pb: 1 }}
        >
          <Button
            variant="contained"
            onClick={() => setPanel(panel === 'modify' ? 'none' : 'modify')}
          >
            ✨ Modify
          </Button>
          <Button variant="contained" color="success" onClick={onFeed}>
            🍖 Feed
          </Button>
          <Button
            variant="contained"
            color="secondary"
            onClick={() => setPanel(panel === 'bag' ? 'none' : 'bag')}
          >
            🎒 Bag
          </Button>
          <Button variant="contained" color="warning" onClick={onTrain} disabled={anim !== null}>
            ⚡ Train{left > 0 ? ` (${left} left today)` : ' — resting'}
          </Button>
        </Box>
        {note && (
          <Typography variant="body2" align="center" sx={{ color: '#cfeef8', pb: 1.5, px: 2 }}>
            {note}
          </Typography>
        )}

        <Collapse in={panel === 'modify'}>
          <Paper sx={{ m: 2, p: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              Modify {fighter.name}
            </Typography>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Crystal tint
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
              {TINTS.map(t => (
                <Chip
                  key={t.label}
                  label={t.label}
                  clickable
                  color={care.tint === t.filter ? 'primary' : 'default'}
                  onClick={() => setCare(updateCare(fighter.name, { tint: t.filter }))}
                />
              ))}
            </Box>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Gear (tap to equip / remove)
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              {GEAR.map(g => (
                <Chip
                  key={g}
                  label={g}
                  clickable
                  color={care.gear.includes(g) ? 'secondary' : 'default'}
                  onClick={() => toggleGear(g)}
                />
              ))}
            </Box>
          </Paper>
        </Collapse>
        <Collapse in={panel === 'bag'}>
          <Paper sx={{ m: 2, p: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              Your bag — give {fighter.name} something
            </Typography>
            <InventoryBagPanel />
          </Paper>
        </Collapse>
      </Box>

      <div className="glacer-stage-chips">
        {roster.map((f, i) => (
          <Chip
            key={f.name}
            label={`${elementEmoji(f.element)} ${f.name}`}
            clickable
            color={i === index ? 'primary' : 'default'}
            onClick={() => goTo(i)}
          />
        ))}
      </div>
      <Typography variant="body2" color="text.secondary" align="center">
        Swipe the stage or tap a name to walk your roster. Training is once a day per navitar —
        twice a day from Lv. {TWICE_DAILY_LEVEL}.
      </Typography>
    </Box>
  );
};

export default NavidexStage;
