import React, { useState } from 'react';
import { Box, Button, Container, MenuItem, Paper, TextField, Typography } from '@mui/material';

// For Venues — the Pilot Host application (Modern View integration,
// Eddie 2026-11-16). A business says "we want to advertise on your
// platform / host battles" here: join the Southern California Pilot
// Corridor as a founding GLACER venue — listed on the World Map as a
// perk venue, host of navitar battles, promoted to players nearby.
//
// HONEST SCOPE: GLACER has no venue-applications backend table yet,
// so a submission is stored on this device (localStorage) and given
// a reference code the venue can quote; wiring this form to a real
// partnerships inbox / Supabase table is a listed pre-launch step in
// the integration report. Nothing here silently pretends to have
// emailed anyone.
export const VENUE_APPLICATIONS_KEY = 'glacer-venue-applications';

interface VenueApplication {
  ref: string;
  venueName: string;
  venueType: string;
  city: string;
  contactName: string;
  email: string;
  phone: string;
  social: string;
  bestNight: string;
  perkIdea: string;
  notes: string;
  submittedAt: string;
}

const VENUE_TYPES = [
  'Bar',
  'Brewery / Taproom',
  'Lounge',
  'Café',
  'Restaurant',
  'Arcade / Gaming',
  'Other',
];
const NIGHTS = ['Thursday', 'Friday', 'Saturday', 'Sunday', 'Weeknight — let’s talk'];

const empty = {
  venueName: '',
  venueType: 'Bar',
  city: '',
  contactName: '',
  email: '',
  phone: '',
  social: '',
  bestNight: 'Friday',
  perkIdea: '',
  notes: '',
};

const VenueJoin: React.FC = () => {
  const [form, setForm] = useState(empty);
  const [error, setError] = useState<string | null>(null);
  const [submitted, setSubmitted] = useState<VenueApplication | null>(null);

  const set = (k: keyof typeof empty) => (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm(prev => ({ ...prev, [k]: e.target.value }));

  const submit = () => {
    if (!form.venueName.trim() || !form.city.trim() || !form.contactName.trim()) {
      setError('Venue name, city, and a contact name are the minimum we need to start.');
      return;
    }
    if (!/^\S+@\S+\.\S+$/.test(form.email.trim())) {
      setError('A valid contact email is required so the GLACER team can reach you.');
      return;
    }
    setError(null);
    const app: VenueApplication = {
      ...form,
      ref: `GLV-${Date.now().toString(36).toUpperCase()}`,
      submittedAt: new Date().toISOString(),
    };
    try {
      const raw = localStorage.getItem(VENUE_APPLICATIONS_KEY);
      const list: VenueApplication[] = raw ? JSON.parse(raw) : [];
      list.push(app);
      localStorage.setItem(VENUE_APPLICATIONS_KEY, JSON.stringify(list));
    } catch {
      // Storage unavailable — the reference screen still shows so the
      // venue can quote it; nothing is silently lost from their view.
    }
    setSubmitted(app);
  };

  if (submitted) {
    return (
      <Container maxWidth="sm" sx={{ py: 5 }}>
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h4" gutterBottom>
            🎉 Application received
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>{submitted.venueName}</strong> is in line for the Southern California Pilot
            Corridor — a founding host of GLACER navitar battles.
          </Typography>
          <Typography variant="body1" paragraph>
            Your reference code: <strong>{submitted.ref}</strong>
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            The GLACER partnerships team reviews pilot hosts personally. Keep your reference code
            handy — it identifies your application. (Preview note: in this build the application is
            stored on this device; live intake wiring is a pre-launch step.)
          </Typography>
          <Button
            variant="contained"
            onClick={() => {
              setSubmitted(null);
              setForm(empty);
            }}
          >
            Add another venue
          </Button>
        </Paper>
      </Container>
    );
  }

  return (
    <Container maxWidth="sm" sx={{ py: 5 }}>
      <Typography variant="h4" gutterBottom align="center">
        For Venues — Become a Pilot Host
      </Typography>
      <Typography variant="body1" color="text.secondary" align="center" paragraph>
        GLACER sends players into real places: they walk in for perks, meet people, and battle
        navitars — at your bar. Pilot hosts in Los Angeles and across Southern California get a
        World Map pin, a Suggested Venue listing, Battle Nights, and a perk they control.
      </Typography>
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>
          Pilot Host application
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <TextField
            label="Venue name"
            value={form.venueName}
            onChange={set('venueName')}
            required
            fullWidth
          />
          <TextField
            label="Venue type"
            select
            value={form.venueType}
            onChange={set('venueType')}
            fullWidth
          >
            {VENUE_TYPES.map(t => (
              <MenuItem key={t} value={t}>
                {t}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="City / neighborhood"
            value={form.city}
            onChange={set('city')}
            required
            fullWidth
            placeholder="Van Nuys, Los Angeles"
          />
          <TextField
            label="Best night for a Battle Night"
            select
            value={form.bestNight}
            onChange={set('bestNight')}
            fullWidth
          >
            {NIGHTS.map(n => (
              <MenuItem key={n} value={n}>
                {n}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Contact name"
            value={form.contactName}
            onChange={set('contactName')}
            required
            fullWidth
          />
          <TextField
            label="Contact email"
            type="email"
            value={form.email}
            onChange={set('email')}
            required
            fullWidth
          />
          <TextField
            label="Phone (optional)"
            value={form.phone}
            onChange={set('phone')}
            fullWidth
          />
          <TextField
            label="Website / social (optional)"
            value={form.social}
            onChange={set('social')}
            fullWidth
          />
          <TextField
            label="The perk you'd offer players"
            value={form.perkIdea}
            onChange={set('perkIdea')}
            fullWidth
            multiline
            minRows={2}
            placeholder="e.g. Show your GLACER check-in for 10% off your first round"
          />
          <TextField
            label="Anything else (optional)"
            value={form.notes}
            onChange={set('notes')}
            fullWidth
            multiline
            minRows={2}
          />
          {error && (
            <Typography variant="body2" color="error">
              {error}
            </Typography>
          )}
          <Button variant="contained" size="large" onClick={submit}>
            Apply to host GLACER battles
          </Button>
          <Typography variant="body2" color="text.secondary">
            No invented terms: pilot pricing, perks, and scheduling are agreed personally with the
            GLACER team — nothing is promised or charged by this form.
          </Typography>
        </Box>
      </Paper>
    </Container>
  );
};

export default VenueJoin;
