import React, { useEffect, useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  Chip,
  IconButton,
  Menu,
  MenuItem,
  Switch,
} from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import { Link as RouterLink } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { DISPLAY_NAME_KEY } from '../utils/accountMerge';
import { useViewMode } from '../contexts/ViewModeContext';

const LINKS = [
  { to: '/battle', label: 'Battle' },
  { to: '/networking', label: 'Networking' },
  { to: '/collection', label: 'Navidex' },
  { to: '/realm', label: 'World Map' },
  { to: '/forums', label: 'Forums' },
  { to: '/messages', label: 'Messages' },
  { to: '/pirates', label: 'Pirates' },
  { to: '/stroll', label: 'Stroll' },
  { to: '/ar', label: 'AR View' },
  { to: '/venues/join', label: 'For Venues' },
  { to: '/features', label: 'All Features' },
  { to: '/profile', label: 'Profile' },
];

// The Modern View's 3D Models toggle (Eddie, 2026-11-16): one
// switch flips every fighter surface between the 2D art and the
// real 3D GLB models — Navidex grid ⇄ stage, and the same value is
// read by Home and Battle. Kept compact so it fits the phone header
// next to the wordmark (the prototype's clipped-toggle bug does not
// ship twice).
const ViewModeToggle: React.FC = () => {
  const { viewMode, toggleViewMode } = useViewMode();
  const is3d = viewMode === '3d';
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mr: 1 }}>
      <Typography variant="caption" sx={{ fontWeight: 700, letterSpacing: '0.04em' }}>
        {is3d ? '3D' : 'ART'}
      </Typography>
      <Switch
        size="small"
        checked={is3d}
        onChange={toggleViewMode}
        inputProps={{ 'aria-label': 'Toggle 3D models' }}
        data-testid="nav-3d-toggle"
      />
      <Typography
        variant="caption"
        sx={{ display: { xs: 'none', sm: 'block' }, color: 'text.secondary' }}
      >
        Models
      </Typography>
    </Box>
  );
};

// The account cluster (Step 4, 2026-11-14): sign-in used to live
// only inside the Profile page, so most players never found it.
// The nav now carries it everywhere: signed out → Log in / Sign up
// (both land on the Profile account card); signed in → a chip with
// the player's name and a Log out button. Signing in is never
// required to play — this is a door, not a wall.
const NavAuthCluster: React.FC<{ onNavigate?: () => void }> = ({ onNavigate }) => {
  const { user, loading, signOut } = useAuth();
  // The chip name: the merged display name (accountMerge keeps the
  // local key in sync with the account), else the email. Re-read on
  // auth changes and whenever the key changes in another surface.
  const [name, setName] = useState<string | null>(null);
  useEffect(() => {
    const read = () => {
      try {
        setName(localStorage.getItem(DISPLAY_NAME_KEY));
      } catch {
        setName(null);
      }
    };
    read();
    window.addEventListener('storage', read);
    return () => window.removeEventListener('storage', read);
  }, [user]);

  if (loading) return null;
  if (!user) {
    return (
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
        <Button
          component={RouterLink}
          to="/profile#account"
          color="inherit"
          size="small"
          data-testid="nav-login"
          onClick={onNavigate}
        >
          Log in
        </Button>
        <Button
          component={RouterLink}
          to="/profile#account"
          variant="outlined"
          color="inherit"
          size="small"
          data-testid="nav-signup"
          onClick={onNavigate}
        >
          Sign up
        </Button>
      </Box>
    );
  }
  return (
    <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
      <Chip
        label={name?.trim() ? name : user.email}
        size="small"
        color="primary"
        data-testid="nav-user-chip"
        component={RouterLink}
        to="/profile"
        clickable
        sx={{ maxWidth: 180 }}
      />
      <Button
        color="inherit"
        size="small"
        data-testid="nav-logout"
        onClick={() => {
          onNavigate?.();
          void signOut();
        }}
      >
        Log out
      </Button>
    </Box>
  );
};

const Navbar: React.FC = () => {
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const menuOpen = Boolean(anchorEl);

  return (
    <AppBar position="static" color="transparent" elevation={1}>
      <Toolbar>
        <Typography
          variant="h6"
          component={RouterLink}
          to="/"
          sx={{
            flexGrow: 1,
            textDecoration: 'none',
            color: 'inherit',
            fontWeight: 'bold',
          }}
        >
          GLACER
        </Typography>

        {/* Desktop: the full row. On phones the row is ~850px wide and
            forces horizontal scrolling, hiding the later links entirely —
            so below the md breakpoint it collapses into a menu. */}
        <Box sx={{ display: { xs: 'none', md: 'flex' }, gap: 2, alignItems: 'center' }}>
          {/* Battle used to be disabled until a navitar was selected in a
              different navitar model than the one the Battle page actually
              uses, so the link could never enable. The Battle page renders
              fine and now offers to create a Navitar when none exists. */}
          {LINKS.map(link => (
            <Button key={link.to} component={RouterLink} to={link.to} color="inherit">
              {link.label}
            </Button>
          ))}
          <ViewModeToggle />
          <NavAuthCluster />
        </Box>

        <Box sx={{ display: { xs: 'flex', md: 'none' }, alignItems: 'center', gap: 1 }}>
          <ViewModeToggle />
          <NavAuthCluster />
          <IconButton
            color="inherit"
            aria-label="Open menu"
            aria-controls={menuOpen ? 'nav-menu' : undefined}
            aria-haspopup="true"
            aria-expanded={menuOpen ? 'true' : undefined}
            onClick={e => setAnchorEl(e.currentTarget)}
          >
            <MenuIcon />
          </IconButton>
          <Menu id="nav-menu" anchorEl={anchorEl} open={menuOpen} onClose={() => setAnchorEl(null)}>
            {LINKS.map(link => (
              <MenuItem
                key={link.to}
                component={RouterLink}
                to={link.to}
                onClick={() => setAnchorEl(null)}
              >
                {link.label}
              </MenuItem>
            ))}
          </Menu>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
