import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';

// Global fighter display mode (Modern View integration, Eddie
// 2026-11-16): 'art' shows the 2D portraits, '3d' shows the real
// GLB models. One toggle in the Navbar drives every surface that
// renders a fighter — the Navidex (grid ⇄ stage), Home's hero and
// the battle stage all read the same value. Persisted per profile
// in localStorage; default is 'art' (lightest first paint, and the
// 3D models load only when the player asks for them).
export type ViewMode = 'art' | '3d';

export const VIEW_MODE_KEY = 'glacer-view-mode';

function readInitial(): ViewMode {
  try {
    return localStorage.getItem(VIEW_MODE_KEY) === '3d' ? '3d' : 'art';
  } catch {
    return 'art';
  }
}

interface ViewModeContextType {
  viewMode: ViewMode;
  setViewMode: (mode: ViewMode) => void;
  toggleViewMode: () => void;
}

const ViewModeContext = createContext<ViewModeContextType>({
  viewMode: 'art',
  setViewMode: () => undefined,
  toggleViewMode: () => undefined,
});

export const ViewModeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [viewMode, setViewModeState] = useState<ViewMode>(readInitial);

  const setViewMode = (mode: ViewMode) => {
    setViewModeState(mode);
    try {
      localStorage.setItem(VIEW_MODE_KEY, mode);
    } catch {
      // Private mode / quota: the choice still holds for the session.
    }
  };

  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === VIEW_MODE_KEY) setViewModeState(e.newValue === '3d' ? '3d' : 'art');
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  return (
    <ViewModeContext.Provider
      value={{
        viewMode,
        setViewMode,
        toggleViewMode: () => setViewMode(viewMode === '3d' ? 'art' : '3d'),
      }}
    >
      {children}
    </ViewModeContext.Provider>
  );
};

export const useViewMode = () => useContext(ViewModeContext);
