import React, { useMemo, useState } from 'react';
import { Box, Button, Chip, Container, Paper, Typography } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import {
  ImHereForControls,
  NetworkingControls,
  PersonStatusChip,
} from '../components/NetworkingStatus';
import { PersonaProfileDialog } from '../components/PersonaProfileDialog';
import { usePresence } from '../contexts/PresenceContext';
import { DEMO_VENUES, type VenuePerson } from '../data/venues';
import { loadFriends } from '../utils/friends';
import { personVisibleToPlayer } from '../utils/presence';

// Networking — the front door to GLACER's social layer (Eddie,
// 2026-11-14: "we need a clear networking link"). Everything on
// this page already existed — presence status + visibility, the
// "I'm here for" match contexts, and the per-person match reasons —
// but it was scattered across Profile and the Realm Map with no
// door of its own. This page gathers it under the name Eddie gave
// it: Networking.
//
// The people list is read-only and honest: it shows who is around
// the realm's venues and WHY you match, under the same visibility
// rules as Who's Here (invisible people never render; business-
// visibility people appear only for their tagged contacts). Meeting
// still happens the conversation-first way — check in on the Realm
// Map and your navitar may bring you an icebreaker.
const Networking: React.FC = () => {
  const { businessContactIds, getMatchReason } = usePresence();
  // Persona profiles (Step 4): a person's row links to their full
  // profile — the dialog is view-only; meeting still starts through
  // check-in and icebreakers, never from here.
  const [profilePerson, setProfilePerson] = useState<{
    person: VenuePerson;
    venueName: string;
  } | null>(null);

  const venueMatches = useMemo(() => {
    const friendIds = loadFriends();
    return DEMO_VENUES.map(venue => ({
      venue,
      people: venue.people
        .filter(p => personVisibleToPlayer(p, { businessContactIds, friendIds }))
        .map(person => ({ person, reason: getMatchReason(person) })),
    })).filter(group => group.people.length > 0);
  }, [businessContactIds, getMatchReason]);

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="networking-page">
      <Typography variant="h4" gutterBottom align="center">
        Networking
      </Typography>
      <Typography variant="body1" color="text.secondary" align="center" sx={{ mb: 4 }}>
        GLACER exists to make social media social again. This is your presence: how open you are,
        who can see you, and why you are here — and the people around the realm you match with.
      </Typography>

      <Paper sx={{ p: 3, mb: 3 }}>
        <NetworkingControls />
        <ImHereForControls />
      </Paper>

      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          People &amp; matches around the realm
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Who is out there right now, and the strongest reason you two might get along. Check in at
          a venue on the Realm Map and your navitar may bring you an icebreaker — a match only ever
          starts a conversation; connecting is a step you choose inside it.
        </Typography>
        {venueMatches.map(({ venue, people }) => (
          <Box key={venue.id} sx={{ mb: 3 }}>
            <Typography variant="subtitle1" gutterBottom>
              {venue.name}{' '}
              <Typography component="span" variant="body2" color="text.secondary">
                · {venue.area}
              </Typography>
            </Typography>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
              {people.map(({ person, reason }) => (
                <Box
                  key={person.id}
                  data-testid={`networking-person-${person.id}`}
                  sx={{
                    p: 2,
                    borderRadius: 3,
                    bgcolor: 'rgba(255,255,255,0.04)',
                  }}
                >
                  <Box
                    sx={{
                      display: 'flex',
                      gap: 1,
                      flexWrap: 'wrap',
                      alignItems: 'center',
                      mb: 0.5,
                    }}
                  >
                    <Typography variant="subtitle2">{person.name}</Typography>
                    <PersonStatusChip status={person.networkingStatus} />
                    {reason && (
                      <Chip
                        size="small"
                        color="primary"
                        label={reason.label}
                        data-testid={`networking-match-${person.id}`}
                      />
                    )}
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    {person.vibe} · with {person.navitarName} (Lv {person.navitarLevel})
                  </Typography>
                  {reason && (
                    <Typography variant="body2" sx={{ mt: 0.5 }}>
                      {reason.detail}
                    </Typography>
                  )}
                  <Button
                    size="small"
                    sx={{ mt: 0.5, textTransform: 'none', px: 0.5 }}
                    data-testid={`networking-profile-${person.id}`}
                    onClick={() => setProfilePerson({ person, venueName: venue.name })}
                  >
                    View profile
                  </Button>
                </Box>
              ))}
            </Box>
          </Box>
        ))}
      </Paper>

      <PersonaProfileDialog
        person={profilePerson?.person ?? null}
        venueName={profilePerson?.venueName ?? null}
        onClose={() => setProfilePerson(null)}
      />

      <Paper
        sx={{ p: 3, textAlign: 'center', bgcolor: 'rgba(33,150,243,0.08)' }}
        data-testid="networking-forums-bridge"
      >
        <Typography variant="h6" gutterBottom>
          Found your people? Plan the get-together.
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Meetups and venue events live on the Forums — start a thread, set the time and place, and
          let the realm show up.
        </Typography>
        <Button component={RouterLink} to="/forums" variant="contained" size="large">
          Plan it in the Forums →
        </Button>
      </Paper>
    </Container>
  );
};

export default Networking;
