import React, { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { Box, Button, ButtonGroup, CircularProgress, Paper, Typography } from '@mui/material';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { resolveNavitarArt } from '../utils/navitarArt';
import { resolveShowcaseModel } from '../utils/modelResolution';
import { AVATAR_OUTFITS, loadAvatarOutfit, saveAvatarOutfit } from '../utils/avatarOutfit';
import type {
  GpsTarget,
  StrollEnvironment,
  StrollWalkerKind,
  TouchKeys,
} from '../components/StrollScene';

// The 3D scene lives behind React.lazy so the (large) three.js code
// splits out of the main bundle and only loads when the Stroll page is
// actually shown — same pattern as ModelViewer. The scene itself uses
// plain three.js, not @react-three/fiber (fiber 9 breaks the React 18
// build outright — see ModelCanvas).
const StrollScene = lazy(() => import('../components/StrollScene'));

// A real browser always defines WebGLRenderingContext; jsdom and
// WebGL-less environments do not. Checking for the constructor (instead
// of calling canvas.getContext) avoids a jsdom "not implemented" console
// error and skips the scene entirely where it cannot run.
function webglAvailable(): boolean {
  if (typeof window === 'undefined') return false;
  const w = window as unknown as { WebGLRenderingContext?: unknown };
  return typeof w.WebGLRenderingContext !== 'undefined';
}

const Stroll: React.FC = () => {
  const { userNavitar, businessNavitars } = useNavitarFightClub();
  // One-shot gate: no WebGL, no scene attempt at all — the page stays a
  // friendly message instead of a blank canvas or a crash.
  const [canRender3d] = useState(() => webglAvailable());
  const [environment, setEnvironment] = useState<StrollEnvironment>('forest');
  // The avatar's outfit: a swappable character look, persisted by id.
  // The scene applies it live; the picker just switches the id.
  const [outfit, setOutfit] = useState(() => loadAvatarOutfit());
  const touchKeys = useRef<TouchKeys>({ forward: false, left: false, right: false, back: false });

  // THE COMPANION (Eddie, 2026-11-14): Stroll has NO navitar picker —
  // the companion is the navitar selected in the Navidex, i.e. the
  // FightClub active navitar (the collection in glacer-user-navitars
  // + the active id in glacer-active-navitar-id; the Navidex, the
  // battle Step 1 picker and Profile all write that same selection).
  // It stays with you here, in regular stroll and in AR alike.
  // The companion's effective 3D model resolves exactly like the
  // battle stage's showcase model: the record's own model first,
  // then a name+element match against the modeled demo opponents,
  // the venue fighters, and the NAVITAR_MODELS registry.
  // The chain itself is shared with the AR View page
  // (utils/modelResolution.ts) so the companion resolves its model
  // identically on every surface.
  const companionModel = userNavitar ? resolveShowcaseModel(userNavitar, businessNavitars) : null;

  const companion = userNavitar
    ? {
        name: userNavitar.name,
        element: userNavitar.element,
        modelUrl: companionModel?.modelUrl,
        modelZoom: companionModel?.modelZoom ?? userNavitar.modelZoom,
        imageUrl: resolveNavitarArt(userNavitar.imageUrl, userNavitar.name),
      }
    : null;
  const companionHasModel = !!companionModel?.modelUrl;

  // COMPANION RULE (Eddie, 2026-11-14): the walker IS the Navidex
  // companion whenever there is one — the wave-4 "Walk as" humanoid
  // toggle is RETIRED (it was a second selection surface, and Eddie
  // banned those in Stroll). The dress-up avatar walks only when the
  // player has no navitar yet. The old glacer-stroll-walk-as
  // preference is simply no longer read.
  const walkerKind: StrollWalkerKind = userNavitar ? 'navitar' : 'avatar';

  // ---------- AR camera mode (Step 6, Eddie 2026-11-14) ----------
  // The page owns the camera stream; the scene renders transparent
  // over it with the companion's REAL 3D model in the frame. States
  // are honest: no model -> an in-stage panel says so and routes to
  // the Navidex; camera denied/unavailable -> a note + the normal
  // stroll keeps running (never a black screen, never a fake feed).
  const [arOn, setArOn] = useState(false);
  const [camState, setCamState] = useState<'off' | 'starting' | 'on' | 'denied' | 'unavailable'>(
    'off'
  );
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const parallax = useRef({ x: 0, y: 0 });
  // The companion HAS a model on paper but the GLB failed to load
  // (phone check, 2026-11-14): in AR that must surface the same
  // honest no-model panel — a card never appears in AR.
  const [arModelFailed, setArModelFailed] = useState(false);
  useEffect(() => {
    setArModelFailed(false);
  }, [companion?.name]);
  const arNoModel = arOn && !!companion && (!companionHasModel || arModelFailed);
  const arLive = arOn && camState === 'on' && !arNoModel;

  const stopStream = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
  };

  useEffect(() => {
    if (!arOn || !companion || !companionHasModel) {
      stopStream();
      setCamState('off');
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      setCamState('unavailable');
      return;
    }
    let cancelled = false;
    setCamState('starting');
    navigator.mediaDevices
      .getUserMedia({ video: { facingMode: 'environment' }, audio: false })
      .then(stream => {
        if (cancelled) {
          stream.getTracks().forEach(t => t.stop());
          return;
        }
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setCamState('on');
      })
      .catch(() => {
        if (!cancelled) setCamState('denied');
      });
    return () => {
      cancelled = true;
    };
  }, [arOn, companion?.name, companionHasModel]);

  useEffect(() => {
    if (camState === 'on' && videoRef.current && streamRef.current) {
      videoRef.current.srcObject = streamRef.current;
    }
  }, [camState]);

  useEffect(() => stopStream, []);

  // Gentle device-orientation parallax while AR is live. No
  // permission is requested: where the browser fires the event the
  // tilt leans the view a little; where it doesn't, nothing moves.
  useEffect(() => {
    if (!arLive) return;
    const onTilt = (e: DeviceOrientationEvent) => {
      const gx = (e.gamma ?? 0) / 30;
      const gy = ((e.beta ?? 40) - 40) / 30;
      parallax.current = {
        x: Math.max(-1, Math.min(1, gx)),
        y: Math.max(-1, Math.min(1, gy)),
      };
    };
    window.addEventListener('deviceorientation', onTilt);
    return () => window.removeEventListener('deviceorientation', onTilt);
  }, [arLive]);

  // "Walk with me" — Pokémon-Go mode. The watch lives here on the
  // page; the scene only reads the latest target. Scale: 1 real
  // metre = 3 scene units, so a real walking pace (~1.4 m/s) moves
  // the navitar at ~4.2 units/s — the same pleasant pace as the
  // manual WALK_SPEED. Fixes closer than 1.5 m to the last accepted
  // one are ignored as GPS jitter. INTEGRITY: this is cosmetic
  // only — it never touches the checked-in venue, presence, or any
  // networking state.
  const GPS_SCALE = 3;
  const [gpsOn, setGpsOn] = useState(false);
  const [gpsNote, setGpsNote] = useState<string | null>(null);
  const gpsTarget = useRef<GpsTarget | null>(null);
  const gpsOrigin = useRef<{ lat: number; lon: number } | null>(null);
  const gpsLast = useRef<{ lat: number; lon: number } | null>(null);
  useEffect(() => {
    if (!gpsOn) {
      gpsTarget.current = null;
      gpsOrigin.current = null;
      gpsLast.current = null;
      setGpsNote(null);
      return;
    }
    if (!('geolocation' in navigator)) {
      setGpsNote('Location is off — guide him with the buttons or WASD');
      return;
    }
    const watchId = navigator.geolocation.watchPosition(
      pos => {
        const { latitude, longitude } = pos.coords;
        if (!gpsOrigin.current) {
          gpsOrigin.current = { lat: latitude, lon: longitude };
          gpsLast.current = { lat: latitude, lon: longitude };
          return;
        }
        const last = gpsLast.current ?? gpsOrigin.current;
        const dLat = (latitude - last.lat) * 110540;
        const dLon = (longitude - last.lon) * 111320 * Math.cos((last.lat * Math.PI) / 180);
        if (Math.hypot(dLat, dLon) < 1.5) return; // jitter — ignore
        gpsLast.current = { lat: latitude, lon: longitude };
        const origin = gpsOrigin.current;
        const east = (longitude - origin.lon) * 111320 * Math.cos((origin.lat * Math.PI) / 180);
        const north = (latitude - origin.lat) * 110540;
        const x = Math.max(-82, Math.min(82, east * GPS_SCALE));
        const z = Math.max(-82, Math.min(82, -north * GPS_SCALE));
        gpsTarget.current = { x, z, heading: Math.atan2(x, z) };
        setGpsNote(null);
      },
      () => {
        setGpsNote('Location is off — guide him with the buttons or WASD');
      },
      { enableHighAccuracy: true, maximumAge: 1000 }
    );
    return () => navigator.geolocation.clearWatch(watchId);
  }, [gpsOn]);

  // Hold-to-walk buttons for touch: pressing one sets the same flag the
  // keyboard sets, releasing clears it. touch-action none so the page
  // doesn't scroll while a button is held.
  const holdProps = (key: keyof TouchKeys) => ({
    onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) => {
      e.preventDefault();
      touchKeys.current[key] = true;
    },
    onPointerUp: () => {
      touchKeys.current[key] = false;
    },
    onPointerLeave: () => {
      touchKeys.current[key] = false;
    },
    onPointerCancel: () => {
      touchKeys.current[key] = false;
    },
    onContextMenu: (e: React.MouseEvent<HTMLButtonElement>) => e.preventDefault(),
  });

  return (
    <Box sx={{ p: 2, maxWidth: 1000, margin: '0 auto' }}>
      <Paper sx={{ p: 2, mb: 2 }}>
        <Typography variant="h4" gutterBottom>
          Stroll
        </Typography>
        <Typography variant="body1" color="text.secondary" paragraph>
          Take a walk with your navitar — through the woods, or down the city streets.
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center' }}>
          <ButtonGroup aria-label="Stroll environment">
            <Button
              variant={environment === 'forest' ? 'contained' : 'outlined'}
              aria-pressed={environment === 'forest'}
              disabled={arLive}
              onClick={() => setEnvironment('forest')}
            >
              🌲 Forest
            </Button>
            <Button
              variant={environment === 'city' ? 'contained' : 'outlined'}
              aria-pressed={environment === 'city'}
              disabled={arLive}
              onClick={() => setEnvironment('city')}
            >
              🌆 City
            </Button>
          </ButtonGroup>
          <Typography variant="body1">
            {companion ? `Strolling with ${companion.name}` : 'Strolling solo — no navitar yet'}
          </Typography>
          <Button component={RouterLink} to="/realm" variant="outlined" sx={{ ml: 'auto' }}>
            Back to map
          </Button>
        </Box>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center', mt: 2 }}>
          <Button
            variant={arOn ? 'contained' : 'outlined'}
            aria-pressed={arOn}
            aria-label="AR camera"
            disabled={!companion}
            onClick={() => setArOn(on => !on)}
          >
            📷 AR camera
          </Button>
          <Button
            variant={gpsOn ? 'contained' : 'outlined'}
            aria-pressed={gpsOn}
            aria-label="Walk with me (GPS)"
            disabled={arLive}
            onClick={() => setGpsOn(on => !on)}
          >
            📍 Walk with me
          </Button>
          {!companion && (
            <Typography variant="body2" color="text.secondary">
              AR needs a navitar companion first — your Navidex companion is the one who appears in
              AR.
            </Typography>
          )}
        </Box>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          {companion
            ? `You are walking as ${companion.name} — your Navidex companion stays with you in Stroll: the world runs three times farther than it used to, and the fog softens the edge.`
            : 'Your avatar walks alone until you have a navitar.'}
        </Typography>
        {arOn && (camState === 'denied' || camState === 'unavailable') && (
          <Typography variant="body2" sx={{ mt: 1, color: 'warning.main' }} role="note">
            📷 Camera unavailable — AR needs camera access, so you&apos;re still strolling normally.
            Check the browser&apos;s camera permission, then toggle AR camera again.
          </Typography>
        )}
        {gpsNote && (
          <Typography variant="body2" sx={{ mt: 1, color: 'warning.main' }} role="note">
            {gpsNote}
          </Typography>
        )}
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          WASD or arrow keys to walk — W forward, A / D to turn, S to step back. On touch, use the
          on-screen buttons. Drag to look around; the camera follows behind you. Trees and buildings
          are scenery for now — you can walk straight through them. With Walk with me on, your
          navitar follows your real footsteps (the buttons and WASD still override); it is a
          cosmetic stroll only — it never changes your check-in or who can see you. AR camera puts
          your companion&apos;s real 3D model in your camera view instead: the same buttons move him
          within the frame (forward = farther away, back = nearer), Walk with me pauses while AR is
          on, and AR never touches check-in or presence either.
        </Typography>
        {/* Outfit picker: the avatar is a character you dress up, not a
            likeness of anyone. New outfits only need an entry in
            src/utils/avatarOutfit.ts to appear here — shop and earned
            looks plug into this same picker later. */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, alignItems: 'center', mt: 2 }}>
          <Typography variant="body2" color="text.secondary">
            Outfit:
          </Typography>
          {AVATAR_OUTFITS.map(o => (
            <Button
              key={o.id}
              size="small"
              variant={outfit.id === o.id ? 'contained' : 'outlined'}
              aria-label={`Wear ${o.name} outfit`}
              aria-pressed={outfit.id === o.id}
              onClick={() => {
                saveAvatarOutfit(o.id);
                setOutfit(o);
              }}
            >
              {o.name} · {o.tag}
            </Button>
          ))}
        </Box>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          Your avatar is a character you can dress up — outfits are swappable, and more looks (shop
          or earned) can plug in here later.
        </Typography>
      </Paper>

      {!userNavitar && (
        <Paper sx={{ p: 2, mb: 2, border: '1px solid', borderColor: 'primary.main' }}>
          <Typography variant="h6" gutterBottom>
            Create a navitar first
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            You can stroll on your own right now, but your navitar will walk beside you once you
            have one.
          </Typography>
          <Button component={RouterLink} to="/battle" variant="contained">
            Create a navitar
          </Button>
        </Paper>
      )}

      {arNoModel && companion ? (
        // Honest no-model state (companion rule): AR never fakes a
        // stand-in, and selection never happens in Stroll — the
        // route leads to the Navidex, the one place a companion is
        // chosen. Rendered in place of the stage (and ahead of the
        // WebGL gate: the no-model fact is the more specific state).
        <Paper
          sx={{
            p: 3,
            minHeight: 300,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 1.5,
            textAlign: 'center',
          }}
        >
          <Typography variant="h6">{companion.name} doesn&apos;t have a 3D model yet</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 420 }}>
            AR stroll shows your companion&apos;s real 3D model in the camera — never a picture or a
            stand-in. Choose a companion with a 3D model in the Navidex and that companion stays
            with you here.
          </Typography>
          <Button component={RouterLink} to="/collection" variant="contained">
            Choose your companion in the Navidex
          </Button>
          <Button onClick={() => setArOn(false)}>Back to stroll</Button>
        </Paper>
      ) : canRender3d ? (
        <Box
          sx={{
            width: '100%',
            height: 560,
            position: 'relative',
            borderRadius: '16px',
            overflow: 'hidden',
            bgcolor: '#121212',
          }}
        >
          {/* The live camera feed sits UNDER the transparent scene
              canvas while AR is on. It renders only in AR; the stream
              attaches via the camState effect above. */}
          {arOn && companionHasModel && camState !== 'off' && (
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              style={{
                position: 'absolute',
                inset: 0,
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                zIndex: 0,
              }}
            />
          )}
          <Box sx={{ position: 'absolute', inset: 0, zIndex: 1 }}>
            <Suspense
              fallback={
                <Box
                  sx={{
                    width: '100%',
                    height: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 1,
                  }}
                >
                  <CircularProgress size={20} />
                  <Typography variant="body2">Loading the stroll…</Typography>
                </Box>
              }
            >
              <StrollScene
                environment={environment}
                companion={companion}
                outfit={outfit}
                touchKeys={touchKeys}
                walkerKind={walkerKind}
                gpsTarget={gpsTarget}
                arMode={arLive}
                parallax={parallax}
                onModelLoadError={() => setArModelFailed(true)}
              />
            </Suspense>
          </Box>
          {/* On-screen walk controls for touch. They sit above the canvas
              so they never fight the drag-to-look gesture. Hidden over
              the AR no-model panel (there is nothing to walk there). */}
          {!arNoModel && (
            <Box
              sx={{
                position: 'absolute',
                right: 16,
                bottom: 16,
                zIndex: 2,
                display: 'grid',
                gridTemplateColumns: 'repeat(3, 52px)',
                gridTemplateRows: 'repeat(2, 52px)',
                gap: 1,
              }}
            >
              <Box />
              <Button
                variant="contained"
                aria-label="Walk forward"
                sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
                {...holdProps('forward')}
              >
                ▲
              </Button>
              <Box />
              <Button
                variant="contained"
                aria-label="Turn left"
                sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
                {...holdProps('left')}
              >
                ◀
              </Button>
              <Button
                variant="contained"
                aria-label="Walk back"
                sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
                {...holdProps('back')}
              >
                ▼
              </Button>
              <Button
                variant="contained"
                aria-label="Turn right"
                sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
                {...holdProps('right')}
              >
                ▶
              </Button>
            </Box>
          )}
        </Box>
      ) : (
        <Paper sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>
            The 3D stroll needs WebGL
          </Typography>
          <Typography variant="body2" color="text.secondary">
            This browser can&apos;t run WebGL, so the stroll can&apos;t load here. Your navitar is
            safe — you can still see it on the map and in your Navidex.
          </Typography>
        </Paper>
      )}
    </Box>
  );
};

export default Stroll;
