// Item inventory — the §11 expansion (world-asset-inventory): Power-Up
// Emeralds, Aegis Shields and Surge Crystals, persisted in localStorage
// as a SIBLING store to the potions (src/utils/potions.ts), whose own
// storage and signatures are the battle deck's contract and stay
// untouched. This module mirrors the potions mold exactly — sanitize /
// persist / get / grant / use — so the two stores read as one family.
//
// The Inventory Bag (§11.4) counts BOTH stores against one capacity:
// bagTotal() / bagHeadroom() below are the single source for "how full
// is the bag" used by stations (honest "Bag full"), duel-win grants
// (never overflow) and the bag panel itself.

import { getPotions } from './potions';

export type ItemId = 'emeralds' | 'shields' | 'crystals';

export interface ItemCounts {
  emeralds: number;
  shields: number;
  crystals: number;
}

export const ITEMS: Record<
  ItemId,
  { name: string; emoji: string; blurb: string; category: 'Power' | 'Shields' | 'Special' }
> = {
  emeralds: {
    name: 'Power-Up Emerald',
    emoji: '💎',
    blurb: 'Power up a navitar: +25 XP each, through the same XP path as a duel win.',
    category: 'Power',
  },
  shields: {
    name: 'Aegis Shield',
    emoji: '🛡️',
    blurb: 'Duel-only: a free action raising a 30-damage absorption pool (after Guard, before HP).',
    category: 'Shields',
  },
  crystals: {
    name: 'Surge Crystal',
    emoji: '🔮',
    blurb: 'Duel-only: a free action — your next Power Strike this duel deals ×1.5 damage.',
    category: 'Special',
  },
};

// One emerald feeds the existing XP system at +25 (levels.ts thresholds
// unchanged — a spend can level a navitar up exactly like a win can).
export const EMERALD_XP = 25;

// The Aegis Shield's absorption pool, sized to mirror the Health
// Potion's 30 HP (§11.2).
export const AEGIS_SHIELD_POOL = 30;

export const BAG_CAPACITY = 50;

const ITEMS_KEY = 'glacer-items';
const CHECKIN_CLAIMS_KEY = 'glacer-emerald-checkins';

function emptyCounts(): ItemCounts {
  return { emeralds: 0, shields: 0, crystals: 0 };
}

function sanitizeCounts(raw: unknown): ItemCounts {
  const counts = emptyCounts();
  if (raw && typeof raw === 'object') {
    const obj = raw as Record<string, unknown>;
    (Object.keys(counts) as ItemId[]).forEach(id => {
      const v = obj[id];
      counts[id] = typeof v === 'number' && Number.isFinite(v) && v > 0 ? Math.floor(v) : 0;
    });
  }
  return counts;
}

export function getItems(): ItemCounts {
  try {
    const raw = localStorage.getItem(ITEMS_KEY);
    if (!raw) return emptyCounts();
    return sanitizeCounts(JSON.parse(raw));
  } catch {
    // Missing or corrupt — never throws, just an empty store.
    return emptyCounts();
  }
}

function persist(counts: ItemCounts): void {
  try {
    localStorage.setItem(ITEMS_KEY, JSON.stringify(counts));
  } catch {
    // Private mode / quota: the counts still hold for this session.
  }
}

export function grantItems(g: Partial<ItemCounts>): ItemCounts {
  const counts = getItems();
  (Object.keys(counts) as ItemId[]).forEach(id => {
    const add = g[id];
    if (typeof add === 'number' && Number.isFinite(add) && add > 0) {
      counts[id] += Math.floor(add);
    }
  });
  persist(counts);
  return counts;
}

export function useItem(id: ItemId): boolean {
  const counts = getItems();
  if (counts[id] <= 0) return false;
  counts[id] -= 1;
  persist(counts);
  return true;
}

// Spend several of one item atomically (the emerald Power Up stepper):
// either the full count comes out or nothing does.
export function spendItems(id: ItemId, amount: number): boolean {
  if (!Number.isFinite(amount) || amount <= 0) return false;
  const counts = getItems();
  const n = Math.floor(amount);
  if (counts[id] < n) return false;
  counts[id] -= n;
  persist(counts);
  return true;
}

// --- The bag (both stores, one capacity) -----------------------------

export function bagTotal(): number {
  const potions = getPotions();
  const items = getItems();
  return (
    potions.health +
    potions.recharge +
    potions.power +
    items.emeralds +
    items.shields +
    items.crystals
  );
}

export function bagHeadroom(): number {
  return Math.max(0, BAG_CAPACITY - bagTotal());
}

// Clamp a prospective grant to the bag's headroom, trimming in the
// order the entries are listed by the caller (win drip first, the
// rare drops last) so grants never overflow and nothing silently
// vanishes — the caller renders exactly what this returns.
export function clampGrantToBag<T extends Partial<ItemCounts & { potions?: number }>>(
  grant: T,
  order: Array<keyof T>
): T {
  let headroom = bagHeadroom();
  const out = { ...grant };
  for (const key of order) {
    const want = typeof out[key] === 'number' ? Math.floor(out[key] as number) : 0;
    const give = Math.max(0, Math.min(want, headroom));
    (out as Record<string, number>)[key as string] = give;
    headroom -= give;
  }
  return out;
}

// --- Venue check-in emerald (§11.1: +1 per venue per day) ------------

function todayKey(): string {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mm}-${dd}`;
}

function loadCheckinClaims(): Record<string, string> {
  try {
    const raw = localStorage.getItem(CHECKIN_CLAIMS_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? (parsed as Record<string, string>) : {};
  } catch {
    return {};
  }
}

// Grants the daily check-in emerald for a venue. Returns true only
// when an emerald actually landed: first claim for that venue today
// AND room in the bag. A full bag does not burn the day's claim — the
// venue simply grants nothing this time (honest, like the stations).
export function claimCheckinEmerald(venueId: string): boolean {
  const claims = loadCheckinClaims();
  if (claims[venueId] === todayKey()) return false;
  if (bagHeadroom() <= 0) return false;
  grantItems({ emeralds: 1 });
  claims[venueId] = todayKey();
  try {
    localStorage.setItem(CHECKIN_CLAIMS_KEY, JSON.stringify(claims));
  } catch {
    // The grant already landed; a lost claim record only risks a
    // second emerald from a re-check-in, never a crash.
  }
  return true;
}

// --- Refill-station drop rolls (§11.1/§11.2/§11.3) --------------------
// Emerald ≈ 1 in 3 collects, Aegis Shield uncommon at 1 in 5, Surge
// Crystal rare at 1 in 10. Rolled independently; the caller clamps
// the result (with the potions) to the bag's headroom.
export function rollStationItemDrops(): ItemCounts {
  return {
    emeralds: Math.random() < 1 / 3 ? 1 : 0,
    shields: Math.random() < 1 / 5 ? 1 : 0,
    crystals: Math.random() < 1 / 10 ? 1 : 0,
  };
}
