import React, { useState } from 'react';
import {
  Box,
  Button,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import {
  POTIONS,
  armPowerBoost,
  getPotions,
  isPowerBoostArmed,
  type PotionId,
} from '../utils/potions';
import { BAG_CAPACITY, EMERALD_XP, ITEMS, bagTotal, getItems, type ItemId } from '../utils/items';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';

// The Inventory Bag (§11.4, world-asset-inventory): one item home
// over the two existing stores — potions (glacer-potions, untouched)
// and items (glacer-items). Lives on Profile (where emeralds are
// spent, next to the collection they power up) and in the battle
// setup behind the Bag button (same panel, fighter preselected).
// Tabs: Potions / Power / Shields / Special. The bag counts every
// item in both stores against BAG_CAPACITY (50); the "+50 bag space"
// upgrade is a concept only — no store, no pricing, nothing to buy.
export const InventoryBagPanel: React.FC<{ defaultNavitarId?: string }> = ({
  defaultNavitarId,
}) => {
  const { navitars, spendEmeraldsOn } = useNavitarFightClub();
  const [tab, setTab] = useState(0);
  const [, setTick] = useState(0);
  const refresh = () => setTick(t => t + 1);
  const [powerTargetId, setPowerTargetId] = useState<string>(defaultNavitarId ?? '');
  const [powerCount, setPowerCount] = useState(1);
  const [powerMessage, setPowerMessage] = useState<string | null>(null);

  const potions = getPotions();
  const items = getItems();
  const total = bagTotal();
  const armed = isPowerBoostArmed();
  const targetId = powerTargetId || defaultNavitarId || navitars[0]?.id || '';
  const target = navitars.find(n => n.id === targetId);
  const maxSpend = Math.max(0, items.emeralds);
  const spendCount = Math.min(Math.max(1, powerCount), Math.max(1, maxSpend));

  const handlePowerUp = () => {
    if (!target) return;
    const result = spendEmeraldsOn(target.id, spendCount);
    if (result.granted) {
      setPowerMessage(
        `+${result.xpAdded} XP to ${target.name} (${result.emeraldsLeft} emeralds left)` +
          (result.leveledUp
            ? ` — 🎉 LEVEL UP! Lv ${result.leveledUp.from} → Lv ${result.leveledUp.to}`
            : '')
      );
      setPowerCount(1);
    } else {
      setPowerMessage('Not enough emeralds for that power up.');
    }
    refresh();
  };

  const row = (
    emoji: string,
    name: string,
    count: number,
    blurb: string,
    action?: React.ReactNode
  ) => (
    <Box
      key={name}
      sx={{ display: 'flex', alignItems: 'center', gap: 1.5, py: 1, flexWrap: 'wrap' }}
    >
      <Typography variant="h6" component="span">
        {emoji}
      </Typography>
      <Box sx={{ flex: '1 1 220px' }}>
        <Typography variant="body1">
          {name} ×{count}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          {blurb}
        </Typography>
      </Box>
      {action}
    </Box>
  );

  return (
    <Paper sx={{ p: 2 }}>
      <Typography variant="h6" gutterBottom>
        🎒 Inventory Bag — {total}/{BAG_CAPACITY}
      </Typography>
      <Tabs value={tab} onChange={(_, v) => setTab(v)} variant="scrollable" scrollButtons="auto">
        <Tab label="Potions" />
        <Tab label="Power" />
        <Tab label="Shields" />
        <Tab label="Special" />
      </Tabs>
      <Box sx={{ pt: 1 }}>
        {tab === 0 &&
          (Object.keys(POTIONS) as PotionId[]).map(id =>
            row(
              POTIONS[id].emoji,
              POTIONS[id].name,
              potions[id],
              POTIONS[id].blurb,
              id === 'power' ? (
                <Button
                  size="small"
                  variant="outlined"
                  disabled={potions.power <= 0 || armed}
                  onClick={() => {
                    if (armPowerBoost()) refresh();
                  }}
                >
                  {armed ? 'Armed for next duel' : 'Arm for next duel'}
                </Button>
              ) : undefined
            )
          )}
        {tab === 1 && (
          <>
            {row(ITEMS.emeralds.emoji, ITEMS.emeralds.name, items.emeralds, ITEMS.emeralds.blurb)}
            {navitars.length > 0 ? (
              <Box
                sx={{ display: 'flex', gap: 1.5, alignItems: 'center', flexWrap: 'wrap', mt: 1 }}
              >
                <FormControl size="small" sx={{ minWidth: 180 }}>
                  <InputLabel id="bag-power-target-label">Power up</InputLabel>
                  <Select
                    labelId="bag-power-target-label"
                    label="Power up"
                    value={targetId}
                    onChange={e => setPowerTargetId(e.target.value)}
                  >
                    {navitars.map(n => (
                      <MenuItem key={n.id} value={n.id}>
                        {n.name} (Lv {n.level})
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={spendCount <= 1}
                    onClick={() => setPowerCount(c => Math.max(1, c - 1))}
                  >
                    −
                  </Button>
                  <Typography variant="body1" sx={{ minWidth: 28, textAlign: 'center' }}>
                    {spendCount}
                  </Typography>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={spendCount >= maxSpend}
                    onClick={() => setPowerCount(c => Math.min(maxSpend, c + 1))}
                  >
                    +
                  </Button>
                </Box>
                <Button
                  variant="contained"
                  disabled={maxSpend <= 0 || !target}
                  onClick={handlePowerUp}
                >
                  Power Up (+{EMERALD_XP * spendCount} XP)
                </Button>
              </Box>
            ) : (
              <Typography variant="body2" color="text.secondary">
                Create a navitar first — emeralds power up a navitar you own.
              </Typography>
            )}
            {powerMessage && (
              <Typography variant="body2" sx={{ mt: 1 }}>
                {powerMessage}
              </Typography>
            )}
          </>
        )}
        {tab === 2 &&
          row(
            ITEMS.shields.emoji,
            ITEMS.shields.name,
            items.shields,
            `${ITEMS.shields.blurb} In-duel only — raise it from the battle deck; there is no button to press here.`
          )}
        {tab === 3 &&
          row(
            ITEMS.crystals.emoji,
            ITEMS.crystals.name,
            items.crystals,
            `${ITEMS.crystals.blurb} In-duel only — fire it from the battle deck; there is no button to press here.`
          )}
      </Box>
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
        Collect items at refill stations on the Realm Map, win them in duels, and earn an emerald
        for each venue check-in (one per venue per day). Bag space upgrades are a future concept —
        nothing here is for sale.
      </Typography>
    </Paper>
  );
};

// Re-exported so surfaces that only need a count line don't reach
// into both stores themselves.
export const bagSummary = (): string => {
  const items = getItems();
  const potions = getPotions();
  const potionTotal = potions.health + potions.recharge + potions.power;
  return `${potionTotal} potions · ${items.emeralds}💎 · ${items.shields}🛡️ · ${items.crystals}🔮 — bag ${bagTotal()}/${BAG_CAPACITY}`;
};

export type { ItemId };
